=== FILE: apb_gpio.v ===
`timescale 1ns/1ps
// apb_gpio: general-purpose I/O block behind an APB4 completer port.
// Implements interface_spec.md (ports, register map, detection, transfers,
// responses, reset) following microarchitecture.md (zero wait states, PINS
// mask, combinational detection, status <= (status & ~clear) | detected).
//
// Register map (byte offsets, word aligned):
//   0x00 DATA_OUT    rw   0x04 DIR        rw   0x08 DATA_IN  ro
//   0x0C INTR_RISE   rw   0x10 INTR_FALL  rw   0x14 INTR_HIGH rw
//   0x18 INTR_LOW    rw   0x1C INTR_ENABLE rw  0x20 INTR_STATUS w1c
// Requires ADDR_WIDTH >= 6 (the spec requires only 8).
module apb_gpio #(
    parameter ADDR_WIDTH = 8,
    parameter N          = 8
) (
    input  wire                  pclk,
    input  wire                  presetn,
    input  wire [ADDR_WIDTH-1:0] paddr,
    input  wire                  psel,
    input  wire                  penable,
    input  wire                  pwrite,
    input  wire [31:0]           pwdata,
    input  wire [3:0]            pstrb,
    output wire [31:0]           prdata,
    output wire                  pready,
    output wire                  pslverr,
    input  wire [N-1:0]          gpio_in,
    output wire [N-1:0]          gpio_out,
    output wire [N-1:0]          gpio_oe,
    output wire                  irq
);

    // Bits 0 .. N-1 set: pins that exist.
    localparam [31:0] PINS = (N >= 32) ? 32'hFFFF_FFFF
                                       : ((32'd1 << N) - 32'd1);

    // ------------------------------------------------------------------
    // APB decode (zero wait states: completion is psel & penable)
    // ------------------------------------------------------------------
    wire        access     = psel & penable;
    wire [3:0]  index      = paddr[5:2];
    wire        upper_zero = ((paddr >> 6) == {ADDR_WIDTH{1'b0}});
    wire        mapped     = (paddr[1:0] == 2'b00) & upper_zero & (index <= 4'd8);
    wire        rd_en      = access & ~pwrite & mapped;
    wire        wr_en      = access & pwrite & mapped;
    wire [31:0] wmask      = {{8{pstrb[3]}}, {8{pstrb[2]}},
                              {8{pstrb[1]}}, {8{pstrb[0]}}} & PINS;
    wire [31:0] wbits      = pwdata & wmask;

    // ------------------------------------------------------------------
    // State
    // ------------------------------------------------------------------
    reg [31:0] data_out_q, dir_q, rise_q, fall_q, high_q, low_q, en_q;
    reg [31:0] status_q, in_q, in_prev_q;

    reg [31:0] data_out_d, dir_d, rise_d, fall_d, high_d, low_d, en_d;
    reg [31:0] status_d, detected, clear, in_wide, rd_mux;

    // gpio_in widened to 32 bits, zeros above N
    always @* begin
        in_wide         = 32'd0;
        in_wide[N-1:0]  = gpio_in;
    end

    // Read/write register next state: merge under the strobe mask
    always @* begin
        data_out_d = data_out_q;
        dir_d      = dir_q;
        rise_d     = rise_q;
        fall_d     = fall_q;
        high_d     = high_q;
        low_d      = low_q;
        en_d       = en_q;
        if (wr_en) begin
            case (index)
                4'd0:    data_out_d = (data_out_q & ~wmask) | wbits;
                4'd1:    dir_d      = (dir_q      & ~wmask) | wbits;
                4'd3:    rise_d     = (rise_q     & ~wmask) | wbits;
                4'd4:    fall_d     = (fall_q     & ~wmask) | wbits;
                4'd5:    high_d     = (high_q     & ~wmask) | wbits;
                4'd6:    low_d      = (low_q      & ~wmask) | wbits;
                4'd7:    en_d       = (en_q       & ~wmask) | wbits;
                default: ; // 2: DATA_IN read only; 8: INTR_STATUS via clear
            endcase
        end
    end

    // Detection and status: a detection beats a clear on the same edge
    always @* begin
        detected = (  (in_q  & ~in_prev_q & rise_q)
                    | (~in_q &  in_prev_q & fall_q)
                    | (in_q  & high_q)
                    | (~in_q & low_q) ) & PINS;
        clear    = (wr_en && (index == 4'd8)) ? wbits : 32'd0;
        status_d = (status_q & ~clear) | detected;
    end

    // Register block: synchronous active-low reset, then q <= d
    always @(posedge pclk) begin
        if (!presetn) begin
            data_out_q <= 32'd0;
            dir_q      <= 32'd0;
            rise_q     <= 32'd0;
            fall_q     <= 32'd0;
            high_q     <= 32'd0;
            low_q      <= 32'd0;
            en_q       <= 32'd0;
            status_q   <= 32'd0;
            in_q       <= 32'd0;
            in_prev_q  <= 32'd0;
        end else begin
            data_out_q <= data_out_d;
            dir_q      <= dir_d;
            rise_q     <= rise_d;
            fall_q     <= fall_d;
            high_q     <= high_d;
            low_q      <= low_d;
            en_q       <= en_d;
            status_q   <= status_d;
            in_q       <= in_wide;
            in_prev_q  <= in_q;
        end
    end

    // Read multiplexer
    always @* begin
        rd_mux = 32'd0;
        case (index)
            4'd0:    rd_mux = data_out_q;
            4'd1:    rd_mux = dir_q;
            4'd2:    rd_mux = in_q;
            4'd3:    rd_mux = rise_q;
            4'd4:    rd_mux = fall_q;
            4'd5:    rd_mux = high_q;
            4'd6:    rd_mux = low_q;
            4'd7:    rd_mux = en_q;
            4'd8:    rd_mux = status_q;
            default: rd_mux = 32'd0;
        endcase
    end

    // ------------------------------------------------------------------
    // Outputs
    // ------------------------------------------------------------------
    assign prdata   = rd_en ? rd_mux : 32'd0;
    assign pready   = 1'b1;
    assign pslverr  = access & (~mapped | (pwrite & (index == 4'd2)));
    assign gpio_out = data_out_q[N-1:0];
    assign gpio_oe  = dir_q[N-1:0];
    assign irq      = |(status_q & en_q);

`ifdef FORMAL
    // Design-intent assertions only; no proof job accompanies this file.
    always @* begin
        assert (pready == 1'b1);
        if (!access) begin
            assert (prdata == 32'd0);
            assert (pslverr == 1'b0);
        end
        if (access && pwrite)
            assert (prdata == 32'd0);
    end

    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge pclk)
        f_past_valid <= 1'b1;

    always @(posedge pclk) begin
        if (f_past_valid && !$past(presetn)) begin
            assert (data_out_q == 32'd0);
            assert (dir_q      == 32'd0);
            assert (en_q       == 32'd0);
            assert (status_q   == 32'd0);
            assert (in_q       == 32'd0);
            assert (in_prev_q  == 32'd0);
        end
    end
`endif

endmodule
=== END FILE ===
=== FILE: apb_gpio_tb.v ===
`timescale 1ns/1ps
// apb_gpio_tb: self-checking directed testbench for apb_gpio.
// Two instances (N=8 and N=32) share one APB bus and are compared with an
// independent 32-bit cycle model (the N=8 copy against the model masked to
// 8 bits), plus literal expectations from the specification.
// Stimulus is driven on the falling edge; combinational outputs are checked
// 1 ns later.
module apb_gpio_tb;

    localparam [7:0]  A_DOUT = 8'h00;
    localparam [7:0]  A_DIR  = 8'h04;
    localparam [7:0]  A_DIN  = 8'h08;
    localparam [7:0]  A_RISE = 8'h0C;
    localparam [7:0]  A_FALL = 8'h10;
    localparam [7:0]  A_HIGH = 8'h14;
    localparam [7:0]  A_LOW  = 8'h18;
    localparam [7:0]  A_EN   = 8'h1C;
    localparam [7:0]  A_STAT = 8'h20;
    localparam [31:0] M8     = 32'h0000_00FF;

    reg         clk = 1'b0;
    reg         presetn;
    reg         psel;
    reg         penable;
    reg         pwrite;
    reg  [7:0]  paddr;
    reg  [31:0] pwdata;
    reg  [3:0]  pstrb;
    reg  [31:0] gpio_in32;

    wire [31:0] prdata8;
    wire [31:0] prdata32;
    wire        pready8;
    wire        pready32;
    wire        pslverr8;
    wire        pslverr32;
    wire [7:0]  gpio_out8;
    wire [7:0]  gpio_oe8;
    wire [31:0] gpio_out32;
    wire [31:0] gpio_oe32;
    wire        irq8;
    wire        irq32;

    integer passed = 0;
    integer failed = 0;
    integer cpass  = 0;
    integer cfail  = 0;
    reg     chk_on = 1'b0;
    integer i;
    integer rc;
    reg [8*64-1:0] nonce;

    apb_gpio #(.ADDR_WIDTH(8), .N(8)) dut8 (
        .pclk(clk), .presetn(presetn), .paddr(paddr), .psel(psel),
        .penable(penable), .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb),
        .prdata(prdata8), .pready(pready8), .pslverr(pslverr8),
        .gpio_in(gpio_in32[7:0]), .gpio_out(gpio_out8), .gpio_oe(gpio_oe8),
        .irq(irq8)
    );

    apb_gpio #(.ADDR_WIDTH(8), .N(32)) dut32 (
        .pclk(clk), .presetn(presetn), .paddr(paddr), .psel(psel),
        .penable(penable), .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb),
        .prdata(prdata32), .pready(pready32), .pslverr(pslverr32),
        .gpio_in(gpio_in32), .gpio_out(gpio_out32), .gpio_oe(gpio_oe32),
        .irq(irq32)
    );

    always #5 clk = ~clk;

    // ------------------------------------------------------------------
    // Reference model (32 pins), written independently of the RTL
    // ------------------------------------------------------------------
    reg [31:0] m_dout, m_dir, m_rise, m_fall, m_high, m_low, m_en, m_stat;
    reg [31:0] m_in_q, m_in_prev;
    reg [31:0] m_wm, m_clr, m_det;
    reg        m_wr;

    function [31:0] strobe_mask(input [3:0] s);
        begin
            strobe_mask = (s[0] ? 32'h0000_00FF : 32'd0)
                        | (s[1] ? 32'h0000_FF00 : 32'd0)
                        | (s[2] ? 32'h00FF_0000 : 32'd0)
                        | (s[3] ? 32'hFF00_0000 : 32'd0);
        end
    endfunction

    function [31:0] model_read(input [7:0] a);
        begin
            case (a)
                8'h00:   model_read = m_dout;
                8'h04:   model_read = m_dir;
                8'h08:   model_read = m_in_q;
                8'h0C:   model_read = m_rise;
                8'h10:   model_read = m_fall;
                8'h14:   model_read = m_high;
                8'h18:   model_read = m_low;
                8'h1C:   model_read = m_en;
                8'h20:   model_read = m_stat;
                default: model_read = 32'd0;
            endcase
        end
    endfunction

    always @* begin
        m_wm  = strobe_mask(pstrb);
        m_wr  = psel && penable && pwrite;
        m_det = (m_in_q & ~m_in_prev & m_rise) | (~m_in_q & m_in_prev & m_fall)
              | (m_in_q & m_high) | (~m_in_q & m_low);
        m_clr = (m_wr && (paddr == 8'h20)) ? (pwdata & m_wm) : 32'd0;
    end

    always @(posedge clk) begin
        if (!presetn) begin
            m_dout    <= 32'd0;
            m_dir     <= 32'd0;
            m_rise    <= 32'd0;
            m_fall    <= 32'd0;
            m_high    <= 32'd0;
            m_low     <= 32'd0;
            m_en      <= 32'd0;
            m_stat    <= 32'd0;
            m_in_q    <= 32'd0;
            m_in_prev <= 32'd0;
        end else begin
            if (m_wr) begin
                case (paddr)
                    8'h00:   m_dout <= (m_dout & ~m_wm) | (pwdata & m_wm);
                    8'h04:   m_dir  <= (m_dir  & ~m_wm) | (pwdata & m_wm);
                    8'h0C:   m_rise <= (m_rise & ~m_wm) | (pwdata & m_wm);
                    8'h10:   m_fall <= (m_fall & ~m_wm) | (pwdata & m_wm);
                    8'h14:   m_high <= (m_high & ~m_wm) | (pwdata & m_wm);
                    8'h18:   m_low  <= (m_low  & ~m_wm) | (pwdata & m_wm);
                    8'h1C:   m_en   <= (m_en   & ~m_wm) | (pwdata & m_wm);
                    default: ;
                endcase
            end
            m_stat    <= (m_stat & ~m_clr) | m_det;
            m_in_q    <= gpio_in32;
            m_in_prev <= m_in_q;
        end
    end

    // Continuous check of pins, irq and pready against the model
    always @(negedge clk) begin
        if (chk_on) begin
            if ((gpio_out32 === m_dout) && (gpio_oe32 === m_dir) &&
                (irq32 === (|(m_stat & m_en))) &&
                (gpio_out8 === m_dout[7:0]) && (gpio_oe8 === m_dir[7:0]) &&
                (irq8 === (|(m_stat[7:0] & m_en[7:0]))) &&
                (pready8 === 1'b1) && (pready32 === 1'b1))
                cpass = cpass + 1;
            else begin
                cfail = cfail + 1;
                $error("pin/irq mismatch at %0t: out32 %h exp %h oe32 %h exp %h irq32 %b irq8 %b",
                       $time, gpio_out32, m_dout, gpio_oe32, m_dir, irq32, irq8);
            end
        end
    end

    // ------------------------------------------------------------------
    // Check and bus tasks
    // ------------------------------------------------------------------
    task chk32(input [31:0] got, input [31:0] expv, input integer id);
        begin
            if (got === expv)
                passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("check %0d at %0t: got %h expected %h", id, $time, got, expv);
            end
        end
    endtask

    task chk1(input got, input expv, input integer id);
        begin
            if (got === expv)
                passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("check %0d at %0t: got %b expected %b", id, $time, got, expv);
            end
        end
    endtask

    task bus_idle;
        begin
            psel    = 1'b0;
            penable = 1'b0;
            pwrite  = 1'b0;
            paddr   = 8'h00;
            pwdata  = 32'd0;
            pstrb   = 4'b0000;
        end
    endtask

    task wait_cycles(input integer n);
        begin
            repeat (n) @(negedge clk);
        end
    endtask

    // Called at a falling edge; returns at the falling edge after completion.
    task apb_write(input [7:0] a, input [31:0] d, input [3:0] s,
                   input err, input integer id);
        begin
            psel = 1'b1; penable = 1'b0; pwrite = 1'b1;
            paddr = a; pwdata = d; pstrb = s;
            #1;
            chk1(pslverr8, 1'b0, id);
            chk1(pslverr32, 1'b0, id);
            chk32(prdata8, 32'd0, id);
            chk32(prdata32, 32'd0, id);
            @(negedge clk);
            penable = 1'b1;
            #1;
            chk1(pready8, 1'b1, id);
            chk1(pready32, 1'b1, id);
            chk1(pslverr8, err, id);
            chk1(pslverr32, err, id);
            chk32(prdata8, 32'd0, id);
            chk32(prdata32, 32'd0, id);
            @(negedge clk);
            bus_idle;
        end
    endtask

    task apb_read(input [7:0] a, input err, input integer id,
                  output [31:0] r32, output [31:0] r8);
        reg [31:0] ev;
        begin
            psel = 1'b1; penable = 1'b0; pwrite = 1'b0;
            paddr = a; pwdata = 32'd0; pstrb = 4'b0000;
            #1;
            chk1(pslverr8, 1'b0, id);
            chk1(pslverr32, 1'b0, id);
            chk32(prdata8, 32'd0, id);
            chk32(prdata32, 32'd0, id);
            @(negedge clk);
            penable = 1'b1;
            #1;
            ev = model_read(a);
            chk1(pready8, 1'b1, id);
            chk1(pready32, 1'b1, id);
            chk1(pslverr8, err, id);
            chk1(pslverr32, err, id);
            chk32(prdata32, ev, id);
            chk32(prdata8, ev & M8, id);
            r32 = prdata32;
            r8  = prdata8;
            @(negedge clk);
            bus_idle;
        end
    endtask

    task rd_expect(input [7:0] a, input err, input [31:0] lit32,
                   input [31:0] lit8, input integer id);
        reg [31:0] v32;
        reg [31:0] v8;
        begin
            apb_read(a, err, id, v32, v8);
            chk32(v32, lit32, id);
            chk32(v8, lit8, id);
        end
    endtask

    task chk_irq(input e32, input e8, input integer id);
        begin
            chk1(irq32, e32, id);
            chk1(irq8, e8, id);
        end
    endtask

    // ------------------------------------------------------------------
    // Directed sequence
    // ------------------------------------------------------------------
    initial begin
        presetn   = 1'b0;
        gpio_in32 = 32'd0;
        bus_idle;
        wait_cycles(3);
        presetn = 1'b1;
        chk_on  = 1'b1;

        // 1. Reset values
        for (i = 0; i < 9; i = i + 1)
            rd_expect({i[5:0], 2'b00}, 1'b0, 32'd0, 32'd0, 1 + i);
        chk32(gpio_out32, 32'd0, 10);
        chk32(gpio_oe32, 32'd0, 11);
        chk32({24'd0, gpio_out8}, 32'd0, 12);
        chk32({24'd0, gpio_oe8}, 32'd0, 13);
        chk_irq(1'b0, 1'b0, 14);

        // 2. DATA_OUT: full, partial strobes, no strobes, bits above N
        apb_write(A_DOUT, 32'hFFFF_FFFF, 4'b1111, 1'b0, 20);
        rd_expect(A_DOUT, 1'b0, 32'hFFFF_FFFF, 32'h0000_00FF, 21);
        apb_write(A_DOUT, 32'h1234_5678, 4'b0101, 1'b0, 22);
        rd_expect(A_DOUT, 1'b0, 32'hFF34_FF78, 32'h0000_0078, 23);
        apb_write(A_DOUT, 32'h0000_0000, 4'b0000, 1'b0, 24);
        rd_expect(A_DOUT, 1'b0, 32'hFF34_FF78, 32'h0000_0078, 25);
        apb_write(A_DOUT, 32'h0000_AB00, 4'b0010, 1'b0, 26);
        rd_expect(A_DOUT, 1'b0, 32'hFF34_AB78, 32'h0000_0078, 27);
        chk32(gpio_out32, 32'hFF34_AB78, 28);
        chk32({24'd0, gpio_out8}, 32'h0000_0078, 29);

        // 3. DIR
        apb_write(A_DIR, 32'hA5A5_5A5A, 4'b1000, 1'b0, 30);
        rd_expect(A_DIR, 1'b0, 32'hA500_0000, 32'h0000_0000, 31);
        apb_write(A_DIR, 32'hA5A5_5A5A, 4'b0001, 1'b0, 32);
        rd_expect(A_DIR, 1'b0, 32'hA500_005A, 32'h0000_005A, 33);
        apb_write(A_DIR, 32'h0000_0100, 4'b0010, 1'b0, 34);
        rd_expect(A_DIR, 1'b0, 32'hA500_015A, 32'h0000_005A, 35);
        chk32(gpio_oe32, 32'hA500_015A, 36);
        chk32({24'd0, gpio_oe8}, 32'h0000_005A, 37);

        // 4. INTR_RISE .. INTR_ENABLE read/write with strobes
        //    (INTR_LOW with pins low sets status while masked)
        for (i = 0; i < 5; i = i + 1) begin
            apb_write(8'h0C + {i[5:0], 2'b00}, 32'hC3C3_C3C3, 4'b1111, 1'b0, 40 + i);
            rd_expect(8'h0C + {i[5:0], 2'b00}, 1'b0, 32'hC3C3_C3C3, 32'h0000_00C3, 40 + i);
            apb_write(8'h0C + {i[5:0], 2'b00}, 32'h0F0F_0F0F, 4'b0110, 1'b0, 40 + i);
            rd_expect(8'h0C + {i[5:0], 2'b00}, 1'b0, 32'hC30F_0FC3, 32'h0000_00C3, 40 + i);
            apb_write(8'h0C + {i[5:0], 2'b00}, 32'h0000_0000, 4'b1111, 1'b0, 40 + i);
            rd_expect(8'h0C + {i[5:0], 2'b00}, 1'b0, 32'h0000_0000, 32'h0000_0000, 40 + i);
        end
        rd_expect(A_STAT, 1'b0, 32'hC3CF_CFC3, 32'h0000_00C3, 46);
        chk_irq(1'b0, 1'b0, 47);
        apb_write(A_EN, 32'h0000_0001, 4'b1111, 1'b0, 48);
        chk_irq(1'b1, 1'b1, 49);
        apb_write(A_EN, 32'h0000_0000, 4'b1111, 1'b0, 50);
        chk_irq(1'b0, 1'b0, 51);
        apb_write(A_STAT, 32'hFFFF_FFFF, 4'b1111, 1'b0, 52);
        rd_expect(A_STAT, 1'b0, 32'h0000_0000, 32'h0000_0000, 53);

        // 5. DATA_IN: sampled after one edge, read only
        gpio_in32 = 32'hDEAD_BEEF;
        rd_expect(A_DIN, 1'b0, 32'hDEAD_BEEF, 32'h0000_00EF, 55);
        apb_write(A_DIN, 32'h0000_0000, 4'b1111, 1'b1, 56);
        rd_expect(A_DIN, 1'b0, 32'hDEAD_BEEF, 32'h0000_00EF, 57);
        apb_write(A_DIN, 32'hFFFF_FFFF, 4'b1111, 1'b1, 58);
        rd_expect(A_STAT, 1'b0, 32'h0000_0000, 32'h0000_0000, 59);
        gpio_in32 = 32'd0;
        wait_cycles(2);

        // 6. PSLVERR policy: unmapped and unaligned addresses
        apb_write(8'h24, 32'd0, 4'b1111, 1'b1, 60);
        apb_write(8'h28, 32'd0, 4'b1111, 1'b1, 61);
        apb_write(8'h3C, 32'd0, 4'b1111, 1'b1, 62);
        apb_write(8'h40, 32'd0, 4'b1111, 1'b1, 63);
        apb_write(8'h44, 32'd0, 4'b1111, 1'b1, 64);
        apb_write(8'h60, 32'd0, 4'b1111, 1'b1, 65);
        apb_write(8'h80, 32'd0, 4'b1111, 1'b1, 66);
        apb_write(8'hC4, 32'd0, 4'b1111, 1'b1, 67);
        apb_write(8'hFC, 32'd0, 4'b1111, 1'b1, 68);
        apb_write(8'h01, 32'd0, 4'b1111, 1'b1, 69);
        apb_write(8'h02, 32'd0, 4'b1111, 1'b1, 70);
        apb_write(8'h03, 32'd0, 4'b1111, 1'b1, 71);
        apb_write(8'h05, 32'd0, 4'b1111, 1'b1, 72);
        apb_write(8'h21, 32'd0, 4'b1111, 1'b1, 73);
        rd_expect(8'h24, 1'b1, 32'd0, 32'd0, 74);
        rd_expect(8'h40, 1'b1, 32'd0, 32'd0, 75);
        rd_expect(8'h44, 1'b1, 32'd0, 32'd0, 76);
        rd_expect(8'h01, 1'b1, 32'd0, 32'd0, 77);
        rd_expect(8'h06, 1'b1, 32'd0, 32'd0, 78);
        rd_expect(8'hFC, 1'b1, 32'd0, 32'd0, 79);
        rd_expect(8'h80, 1'b1, 32'd0, 32'd0, 80);
        rd_expect(A_DOUT, 1'b0, 32'hFF34_AB78, 32'h0000_0078, 81);
        rd_expect(A_DIR, 1'b0, 32'hA500_015A, 32'h0000_005A, 82);

        // 7a. Rising edge, masking, partial write-1-to-clear
        apb_write(A_RISE, 32'h8000_0003, 4'b1111, 1'b0, 100);
        gpio_in32 = 32'h8000_0003;
        wait_cycles(2);
        rd_expect(A_STAT, 1'b0, 32'h8000_0003, 32'h0000_0003, 101);
        chk_irq(1'b0, 1'b0, 102);
        apb_write(A_EN, 32'h8000_0000, 4'b1111, 1'b0, 103);
        chk_irq(1'b1, 1'b0, 104);
        apb_write(A_STAT, 32'h0000_0002, 4'b1111, 1'b0, 105);
        rd_expect(A_STAT, 1'b0, 32'h8000_0001, 32'h0000_0001, 106);
        chk_irq(1'b1, 1'b0, 107);
        apb_write(A_EN, 32'h0000_0001, 4'b0001, 1'b0, 108);
        rd_expect(A_EN, 1'b0, 32'h8000_0001, 32'h0000_0001, 109);
        chk_irq(1'b1, 1'b1, 110);
        apb_write(A_STAT, 32'h0000_0001, 4'b0001, 1'b0, 111);
        rd_expect(A_STAT, 1'b0, 32'h8000_0000, 32'h0000_0000, 112);
        chk_irq(1'b1, 1'b0, 113);
        apb_write(A_STAT, 32'h8000_0000, 4'b0111, 1'b0, 114);
        rd_expect(A_STAT, 1'b0, 32'h8000_0000, 32'h0000_0000, 115);
        apb_write(A_STAT, 32'h8000_0000, 4'b1000, 1'b0, 116);
        rd_expect(A_STAT, 1'b0, 32'h0000_0000, 32'h0000_0000, 117);
        chk_irq(1'b0, 1'b0, 118);
        wait_cycles(3);
        rd_expect(A_STAT, 1'b0, 32'h0000_0000, 32'h0000_0000, 119);
        apb_write(A_EN, 32'h0000_0000, 4'b1111, 1'b0, 120);
        apb_write(A_RISE, 32'h0000_0000, 4'b1111, 1'b0, 121);

        // 7b. Falling edge, fires once
        apb_write(A_FALL, 32'h8000_0003, 4'b1111, 1'b0, 130);
        gpio_in32 = 32'h0000_0000;
        wait_cycles(2);
        rd_expect(A_STAT, 1'b0, 32'h8000_0003, 32'h0000_0003, 131);
        apb_write(A_STAT, 32'hFFFF_FFFF, 4'b1111, 1'b0, 132);
        rd_expect(A_STAT, 1'b0, 32'h0000_0000, 32'h0000_0000, 133);
        wait_cycles(3);
        rd_expect(A_STAT, 1'b0, 32'h0000_0000, 32'h0000_0000, 134);
        apb_write(A_FALL, 32'h0000_0000, 4'b1111, 1'b0, 135);

        // 7c. High level: sets again after a clear while the level holds
        apb_write(A_HIGH, 32'h0000_0004, 4'b1111, 1'b0, 140);
        gpio_in32 = 32'h0000_0004;
        wait_cycles(2);
        rd_expect(A_STAT, 1'b0, 32'h0000_0004, 32'h0000_0004, 141);
        apb_write(A_STAT, 32'h0000_0004, 4'b1111, 1'b0, 142);
        rd_expect(A_STAT, 1'b0, 32'h0000_0004, 32'h0000_0004, 143);
        gpio_in32 = 32'h0000_0000;
        wait_cycles(2);
        apb_write(A_STAT, 32'h0000_0004, 4'b1111, 1'b0, 144);
        rd_expect(A_STAT, 1'b0, 32'h0000_0000, 32'h0000_0000, 145);
        apb_write(A_HIGH, 32'h0000_0000, 4'b1111, 1'b0, 146);

        // 7d. Low level
        apb_write(A_LOW, 32'h0000_0010, 4'b1111, 1'b0, 150);
        rd_expect(A_STAT, 1'b0, 32'h0000_0010, 32'h0000_0010, 151);
        gpio_in32 = 32'h0000_0010;
        wait_cycles(2);
        apb_write(A_STAT, 32'h0000_0010, 4'b1111, 1'b0, 152);
        rd_expect(A_STAT, 1'b0, 32'h0000_0000, 32'h0000_0000, 153);
        apb_write(A_LOW, 32'h0000_0000, 4'b1111, 1'b0, 154);
        gpio_in32 = 32'h0000_0000;
        wait_cycles(2);

        // 7e. A detection beats a clear on the same edge
        apb_write(A_RISE, 32'h0000_0001, 4'b1111, 1'b0, 160);
        gpio_in32 = 32'h0000_0001;
        wait_cycles(2);
        rd_expect(A_STAT, 1'b0, 32'h0000_0001, 32'h0000_0001, 161);
        gpio_in32 = 32'h0000_0000;
        wait_cycles(2);
        rd_expect(A_STAT, 1'b0, 32'h0000_0001, 32'h0000_0001, 162);
        gpio_in32 = 32'h0000_0001;               // rise detected on the clear's edge
        apb_write(A_STAT, 32'h0000_0001, 4'b1111, 1'b0, 163);
        rd_expect(A_STAT, 1'b0, 32'h0000_0001, 32'h0000_0001, 164);
        apb_write(A_STAT, 32'h0000_0001, 4'b1111, 1'b0, 165);
        rd_expect(A_STAT, 1'b0, 32'h0000_0000, 32'h0000_0000, 166);
        apb_write(A_RISE, 32'h0000_0000, 4'b1111, 1'b0, 167);
        gpio_in32 = 32'h0000_0000;
        wait_cycles(2);

        // 7f. Both edges enabled on one pin
        apb_write(A_RISE, 32'h0000_0020, 4'b1111, 1'b0, 170);
        apb_write(A_FALL, 32'h0000_0020, 4'b1111, 1'b0, 171);
        gpio_in32 = 32'h0000_0020;
        wait_cycles(2);
        rd_expect(A_STAT, 1'b0, 32'h0000_0020, 32'h0000_0020, 172);
        apb_write(A_STAT, 32'h0000_0020, 4'b1111, 1'b0, 173);
        rd_expect(A_STAT, 1'b0, 32'h0000_0000, 32'h0000_0000, 174);
        gpio_in32 = 32'h0000_0000;
        wait_cycles(2);
        rd_expect(A_STAT, 1'b0, 32'h0000_0020, 32'h0000_0020, 175);
        apb_write(A_STAT, 32'h0000_0020, 4'b1111, 1'b0, 176);
        rd_expect(A_STAT, 1'b0, 32'h0000_0000, 32'h0000_0000, 177);
        apb_write(A_RISE, 32'h0000_0000, 4'b1111, 1'b0, 178);
        apb_write(A_FALL, 32'h0000_0000, 4'b1111, 1'b0, 179);

        // 7g. One-cycle pulse
        apb_write(A_RISE, 32'h0000_0040, 4'b1111, 1'b0, 180);
        gpio_in32 = 32'h0000_0040;
        @(negedge clk);
        gpio_in32 = 32'h0000_0000;
        wait_cycles(2);
        rd_expect(A_STAT, 1'b0, 32'h0000_0040, 32'h0000_0040, 181);
        apb_write(A_STAT, 32'h0000_0040, 4'b1111, 1'b0, 182);
        rd_expect(A_STAT, 1'b0, 32'h0000_0000, 32'h0000_0000, 183);
        apb_write(A_RISE, 32'h0000_0000, 4'b1111, 1'b0, 184);

        // 7h. Level on a pin above N=8: only the N=32 copy interrupts
        apb_write(A_EN, 32'hFFFF_FFFF, 4'b1111, 1'b0, 190);
        apb_write(A_HIGH, 32'h0001_0000, 4'b1111, 1'b0, 191);
        gpio_in32 = 32'h0001_0000;
        wait_cycles(2);
        chk_irq(1'b1, 1'b0, 192);
        rd_expect(A_STAT, 1'b0, 32'h0001_0000, 32'h0000_0000, 193);
        gpio_in32 = 32'h0000_0000;
        wait_cycles(2);
        apb_write(A_STAT, 32'hFFFF_FFFF, 4'b1111, 1'b0, 194);
        rd_expect(A_STAT, 1'b0, 32'h0000_0000, 32'h0000_0000, 195);
        chk_irq(1'b0, 1'b0, 196);
        apb_write(A_HIGH, 32'h0000_0000, 4'b1111, 1'b0, 197);

        // 8. Reset again with state and a pending interrupt
        apb_write(A_HIGH, 32'h0000_0001, 4'b1111, 1'b0, 200);
        gpio_in32 = 32'h0000_0001;
        wait_cycles(2);
        chk_irq(1'b1, 1'b1, 201);
        gpio_in32 = 32'h0000_0000;
        presetn   = 1'b0;
        wait_cycles(2);
        chk32(gpio_out32, 32'd0, 202);
        chk32(gpio_oe32, 32'd0, 203);
        chk32({24'd0, gpio_out8}, 32'd0, 204);
        chk32({24'd0, gpio_oe8}, 32'd0, 205);
        chk_irq(1'b0, 1'b0, 206);
        presetn = 1'b1;
        for (i = 0; i < 9; i = i + 1)
            rd_expect({i[5:0], 2'b00}, 1'b0, 32'd0, 32'd0, 210 + i);
        apb_write(A_DOUT, 32'h0000_0001, 4'b1111, 1'b0, 220);
        rd_expect(A_DOUT, 1'b0, 32'h0000_0001, 32'h0000_0001, 221);

        // Verdict
        wait_cycles(2);
        #1;
        chk_on = 1'b0;
        nonce  = {64{8'h00}};
        rc     = $value$plusargs("nirmaan_nonce=%s", nonce);
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed + cpass, failed + cfail);
        $finish;
    end

endmodule
